package com.akshay.stockflow.procurement;
import com.akshay.stockflow.auth.UserAccount; import com.akshay.stockflow.product.*; import com.akshay.stockflow.supplier.*; import jakarta.transaction.Transactional; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/purchase-requests") public class PurchaseRequestController {
private final PurchaseRequestRepository requests; private final SupplierRepository suppliers; private final ProductRepository products; private final PurchaseOrderRepository orders;
public PurchaseRequestController(PurchaseRequestRepository requests,SupplierRepository suppliers,ProductRepository products,PurchaseOrderRepository orders){this.requests=requests;this.suppliers=suppliers;this.products=products;this.orders=orders;}
@GetMapping public List<PurchaseRequest> all(@AuthenticationPrincipal UserAccount user){return user.getRole()==com.akshay.stockflow.auth.Role.EMPLOYEE?requests.findAllByRequestedByOrderByCreatedAtDesc(user.getUsername()):requests.findAllByOrderByCreatedAtDesc();}
@PostMapping @ResponseStatus(HttpStatus.CREATED) public PurchaseRequest create(@Valid @RequestBody RequestInput input,@AuthenticationPrincipal UserAccount requester){Supplier supplier=suppliers.findById(input.supplierId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Supplier not found"));if(!supplier.isActive())throw new ResponseStatusException(HttpStatus.CONFLICT,"Supplier is inactive");List<PurchaseRequestLine> lines=input.lines().stream().map(line->{Product p=products.findById(line.productId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found: "+line.productId()));return new PurchaseRequestLine(p.getId(),p.getSku(),p.getName(),line.quantity(),line.unitCost());}).toList();return requests.save(new PurchaseRequest(supplier.getId(),supplier.getName(),requester.getUsername(),lines));}
@PatchMapping("/{id}/decision") @Transactional public PurchaseRequest decide(@PathVariable Long id,@Valid @RequestBody DecisionInput input,@AuthenticationPrincipal UserAccount reviewer){PurchaseRequest request=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Purchase request not found"));if(request.getStatus()!=PurchaseRequest.Status.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Purchase request has already been reviewed");if(input.approved()){Supplier supplier=suppliers.findById(request.getSupplierId()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"Supplier no longer exists"));if(!supplier.isActive())throw new ResponseStatusException(HttpStatus.CONFLICT,"Supplier is inactive");for(PurchaseRequestLine line:request.getLines()){if(products.findById(line.getProductId()).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Requested product no longer exists: "+line.getSku());}List<PurchaseOrderLine> lines=request.getLines().stream().map(l->new PurchaseOrderLine(l.getProductId(),l.getSku(),l.getProductName(),l.getQuantity(),l.getUnitCost())).toList();PurchaseOrder order=orders.save(new PurchaseOrder(supplier.getId(),supplier.getName(),lines));request.approve(reviewer.getUsername(),input.note(),order.getId());}else request.reject(reviewer.getUsername(),input.note());return requests.save(request);}
public record RequestInput(@NotNull Long supplierId,@NotEmpty List<@Valid LineInput> lines){} public record LineInput(@NotNull Long productId,@Min(1) @Max(1000000) int quantity,@DecimalMin("0.0") double unitCost){} public record DecisionInput(boolean approved,@Size(max=500) String note){}
}
